#define DINGHY_HOST 1
#define FR_VOICES 1
/* SPDX-License-Identifier: GPL-3.0-only */
/* Frodhes engine: the physically modelled Rhodes voice (IMPLEMENTATION-v3 §4.3, §5).
 *
 * Per voice: a hammer force pulse (shapes from a host contact simulation) drives the tine's normal modes (V1 the
 * tine-bar sustain mode exactly on f0, V2 the other tine-bar mode, O1/O2 the tine's 2nd/3rd modes, H1 the
 * horizontal polarisation in Phase 3). Each mode is an exact-pole coupled-form resonator ("MC3") with first-order
 * error feedback. The tip displacement goes through the electromagnetic pickup: a radial flux table Phi~(s),
 * s = (x + off)^2 + h^2, evaluated by cubic Hermite, output = the exact flux difference. The voices sum into a
 * mono mix that passes the pickup load (RLC biquad). All the physics is precomputed per key on the host
 * (tools/gen_rhodes.py -> firmware/gen/rhodes_tables.h).
 *
 * Main loop interface (unchanged for frodhes.c):
 *   jf_rh_note_on(note, vel), jf_rh_note_off(note, rvel), jf_rh_pedal(on) / jf_rh_pedal_level(cc)   post events
 *   jf_rh_quiet(), jf_rh_lit(base, n), jf_rh_hold                                            read summaries
 * ISR: jf_rh_render(mono, n) writes n mono samples (Q15) for the effects chain.
 * The ISR owns every voice; the main loop only posts 32-bit events into a single-producer ring (P1). */
#ifndef FR_RAM
#define FR_RAM                                  /* (frodhes.c: the audio hot loops in RAM) */
#define FR_FAR(fn) fn
#endif
/* SPDX-License-Identifier: GPL-3.0-only */
/* Fixed-point helpers for Frodhes (IMPLEMENTATION-v3 §4.1). The only place they are defined.
 * Every product is a widening int32 x int32 -> int64; shifts of signed values are arithmetic (floor).
 * No 64-bit division anywhere (docs/RULES.md). */
#ifndef jf_FXP_H
#define jf_FXP_H
#include <stdint.h>

static inline int32_t jf_mul30(int32_t a, int32_t b) { return (int32_t)(((int64_t)a * b) >> 30); }
static inline int32_t jf_mul28(int32_t a, int32_t b) { return (int32_t)(((int64_t)a * b) >> 28); }
static inline int32_t jf_mul25(int32_t a, int32_t b) { return (int32_t)(((int64_t)a * b) >> 25); }
static inline int32_t jf_mul16(int32_t a, int32_t b) { return (int32_t)(((int64_t)a * b) >> 16); }
static inline int32_t jf_mul15(int32_t a, int32_t b) { return (int32_t)(((int64_t)a * b) >> 15); }
static inline int32_t jf_mul15s(int32_t a, int32_t b) { return (a * b) >> 15; }   /* |a|, |b| <= 32768 */
static inline int32_t jf_sat15(int32_t v) { return v > 32767 ? 32767 : v < -32767 ? -32767 : v; }
static inline int32_t jf_sat28(int64_t v)
{
    return v > ((1 << 28) - 1) ? ((1 << 28) - 1) : v < -((1 << 28) - 1) ? -((1 << 28) - 1) : (int32_t)v;
}
static inline int32_t jf_lerp15(int32_t a, int32_t b, int32_t f) { return a + (((b - a) * f) >> 15); }
static inline __attribute__((always_inline)) int32_t jf_iabs(int32_t v) { return v < 0 ? -v : v; }
/* fm1_ticks() (24 MHz) to samples at 44.1 kHz, no division: 2^32 * 44100 / 24e6 = 7892002.4 */
static inline uint32_t jf_ticks_to_samples(uint32_t t) { return (uint32_t)(((uint64_t)t * 7892002u) >> 32); }
#endif

#ifndef RING_PUBLISH
#define RING_PUBLISH() do { } while (0)     /* host mode: one thread, no barrier needed */
#endif

/* ---- generated-table types (must match tools/gen_rhodes.py) */
typedef struct { int32_t sh, ch, th, d, drel, cr, b; } jf_rh_mode_t;
typedef struct {
    jf_rh_mode_t m[5];
    int32_t off, gain, kill, hc, pk;
    uint16_t prate, life;
    uint8_t band, fam, res, pad;
} jf_rh_key_t;
typedef struct {              /* physical voicing per TYPE (params.json "types"); STAGE 77 = all unity */
    int32_t off_delta;        /* Q25 gap: pickup jf_offset change (+ = toward the pole axis) */
    int32_t bark, bark_g;     /* Q16: tip / gap scale (pickup distance) and its gain compensation */
    int32_t bell, ham;        /* Q16: overtone force scale, hammer contact-rate scale */
    uint8_t nbody, drive_row; /* body biquads in use (jf_RH_BODY), the drive's row */
} jf_rh_type_t;
